#!/usr/bin/env python3
"""lib/make_kernel.py — Generates notebook.ipynb for Kaggle Debian Server.

Injects environment variables from .env:
  - CLOUDFLARE_TUNNEL_TOKEN
  - CLUSTER_URL (https://your-subdomain.example.com)
  - CLUSTER_AUTH_USER
  - CLUSTER_AUTH_PASS
  - Local SSH public key (if found in ~/.ssh/id_ed25519.pub or ~/.ssh/id_rsa.pub)
"""

from __future__ import annotations

import base64
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)


def load_env(env_path: str) -> dict[str, str]:
    env = {}
    if os.path.exists(env_path):
        with open(env_path) as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = k.strip()
                v = v.strip().strip("'\"")
                if k:
                    env[k] = v
    return env


def get_local_ssh_pubkey() -> str:
    ssh_dir = os.path.expanduser("~/.ssh")
    for key_name in ("id_ed25519.pub", "id_rsa.pub", "authorized_keys"):
        p = os.path.join(ssh_dir, key_name)
        if os.path.exists(p):
            try:
                with open(p) as f:
                    content = f.read().strip().splitlines()
                    if content:
                        return content[0]
            except Exception:
                pass
    return ""


def generate_notebook(output_path: str):
    env_file = os.path.join(ROOT, ".env")
    env = load_env(env_file)

    cf_token = env.get("CLOUDFLARE_TUNNEL_TOKEN", "")
    cluster_url = env.get("CLUSTER_URL", "https://your-subdomain.example.com")
    auth_user = env.get("CLUSTER_AUTH_USER", "")
    auth_pass = env.get("CLUSTER_AUTH_PASS", "")
    if not auth_user or not auth_pass:
        raise SystemExit(
            "ERROR: CLUSTER_AUTH_USER and CLUSTER_AUTH_PASS must be set in .env "
            "(the generated notebook embeds them; never commit it)."
        )
    pub_key = get_local_ssh_pubkey()

    # Read server_gateway.py and encode as base64 for 100% escape-free injection
    with open(os.path.join(HERE, "server_gateway.py"), "rb") as f:
        gateway_b64 = base64.b64encode(f.read()).decode("ascii")

    # Cell 4 source (template + placeholders; avoids f-string escaping)
    cell4_template = "# Cell 4: Launch Gateway & Cloudflare Named Tunnel\nimport os, subprocess, sys, time, urllib.request, base64\n\nCF_TOKEN = \"\"\nCLUSTER_URL = \"__CLUSTER_URL__\"\nAUTH_USER = \"__AUTH_USER__\"\nAUTH_PASS = \"__AUTH_PASS__\"\n\n# 1. Unpack server_gateway.py from clean base64 payload\ngateway_path = \"/kaggle/working/server_gateway.py\"\nGATEWAY_B64 = \"\"\"\"\"\"\nwith open(gateway_path, \"wb\") as f:\n    f.write(base64.b64decode(GATEWAY_B64))\n\n# Launch the gateway on port 8080\nos.environ[\"SERVER_PORT\"] = \"8080\"\nos.environ[\"SSH_PORT\"] = \"22\"\nos.environ[\"TTYD_PORT\"] = \"7681\"\nos.environ[\"CLUSTER_AUTH_USER\"] = AUTH_USER\nos.environ[\"CLUSTER_AUTH_PASS\"] = AUTH_PASS\n\nsubprocess.Popen([sys.executable, gateway_path])\nprint(\">>> Server Gateway launched on 0.0.0.0:8080\")\n\n# Launch JupyterLab on port 8888 (for tunnel jupyter command)\nos.environ[\"JUPYTER_CONFIG_DIR\"] = \"/kaggle/working/.jupyter\"\nos.makedirs(\"/kaggle/working/.jupyter\", exist_ok=True)\njupyter_config = \"\"\"\nc.ServerApp.ip = '127.0.0.1'\nc.ServerApp.port = 8888\nc.ServerApp.open_browser = False\nc.ServerApp.allow_remote_access = False\nc.ServerApp.token = ''\nc.ServerApp.password = ''\nc.ServerApp.allow_root = True\nc.ServerApp.root_dir = '/kaggle/working'\nc.ServerApp.allow_origin = '*'\nc.ServerApp.disable_check_xsrf = True\n\"\"\"\nwith open(\"/kaggle/working/.jupyter/jupyter_notebook_config.py\", \"w\") as f:\n    f.write(jupyter_config)\njupyter_env = os.environ.copy()\njupyter_env[\"HOME\"] = \"/kaggle/working\"\nsubprocess.Popen(\n    [sys.executable, \"-m\", \"jupyter\", \"lab\"],\n    env=jupyter_env,\n    stdout=open(\"/kaggle/working/jupyter.log\", \"a\"),\n    stderr=subprocess.STDOUT\n)\nprint(\">>> JupyterLab launched on 127.0.0.1:8888 (no token)\")\n\n# 2. Download and run Cloudflare Tunnel\ncf_bin = \"/kaggle/working/cache/bin/cloudflared\"\nif not os.path.exists(cf_bin):\n    print(\">>> Downloading cloudflared binary...\")\n    urllib.request.urlretrieve(\"https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64\", cf_bin)\n    os.chmod(cf_bin, 0o755)\n\ncf_log = \"/kaggle/working/cloudflared.log\"\nfh = open(cf_log, \"w\")\nprint(\">>> Starting named Cloudflare tunnel with dedicated token...\", flush=True)\nproc = subprocess.Popen([cf_bin, \"tunnel\", \"--no-autoupdate\", \"run\", \"--token\", CF_TOKEN, \"--url\", \"http://127.0.0.1:8080\"],\n                        stdout=fh, stderr=subprocess.STDOUT)\ntime.sleep(5)\nif proc.poll() is not None:\n    fh.flush()\n    print(\"Cloudflared failed to start! Log:\", open(cf_log).read()[-1000:])\n    raise RuntimeError(\"Cloudflare tunnel exited unexpectedly\")\n\nprint(\"=\" * 72)\nprint(\"\ud83d\ude80 KAGGLE DEBIAN SERVER IS LIVE!\")\nprint(f\"Web Dashboard : {CLUSTER_URL}\")\nprint(f\"Web Terminal  : {CLUSTER_URL}/terminal\")\nprint(f\"SSH Endpoint  : {CLUSTER_URL}/ws/ssh\")\nprint(f\"Auth Username : {AUTH_USER}\")\nprint(\"=\" * 72)\n\n"
    CELL4_SOURCE = (cell4_template
        .replace('__CF_TOKEN__', cf_token)
        .replace('__CLUSTER_URL__', cluster_url)
        .replace('__AUTH_USER__', auth_user)
        .replace('__AUTH_PASS__', auth_pass)
        .replace('__GATEWAY_B64__', gateway_b64))

    # -------------------------------------------------------------------------
    # Notebook Cells
    # -------------------------------------------------------------------------
    cells = [
        # Cell 1: Environment & Directories
        {
            "cell_type": "code",
            "execution_count": None,
            "metadata": {},
            "outputs": [],
            "source": f"""# Cell 1: Environment discovery and cache directory layout
import os, sys, platform, subprocess, shutil

print("=== KAGGLE DEBIAN LINUX SERVER ===")
print("Python   :", sys.version.split()[0])
print("Platform :", platform.platform())

# Cache paths for zero-reinstall persistence
os.makedirs("/kaggle/working/cache/apt/archives", exist_ok=True)
os.makedirs("/kaggle/working/cache/pip", exist_ok=True)
os.makedirs("/kaggle/working/cache/bin", exist_ok=True)
os.makedirs("/kaggle/working/workspace", exist_ok=True)

# GPU inspection
try:
    gpu = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv"],
                         capture_output=True, text=True).stdout
    print("GPU Info :\\n", gpu.strip() if gpu else "No GPU detected (running on CPU)")
except Exception as e:
    print("GPU Info : None (CPU mode)")

st = shutil.disk_usage("/kaggle/working")
print(f"Working Storage : Total {{st.total / 1e9:.1f}} GB | Free {{st.free / 1e9:.1f}} GB")
"""
        },

        # Cell 2: Persistence & Cache Restore System ("Saved from Reinstalling")
        {
            "cell_type": "code",
            "execution_count": None,
            "metadata": {},
            "outputs": [],
            "source": f"""# Cell 2: Persistence & Package Restore System
import os, sys, subprocess, shutil, tarfile

print(">>> Configuring APT cache to /kaggle/working/cache/apt/archives ...")
# 1. Point APT cache to persistent storage so every downloaded .deb is saved
apt_conf = '''
Dir::Cache::Archives "/kaggle/working/cache/apt/archives";
Binary::apt::APT::Keep-Downloaded-Packages "true";
'''
os.makedirs("/etc/apt/apt.conf.d", exist_ok=True)
with open("/etc/apt/apt.conf.d/99persistent-cache", "w") as f:
    f.write(apt_conf.strip() + "\\n")

# 2. Check for existing state bundle (debian_server_state.tar.gz)
STATE_BUNDLE = "/kaggle/working/debian_server_state.tar.gz"
if os.path.exists(STATE_BUNDLE):
    print(f">>> Found saved state bundle ({{os.path.getsize(STATE_BUNDLE)/1e6:.1f}} MB)! Restoring...")
    try:
        with tarfile.open(STATE_BUNDLE, "r:gz") as tar:
            tar.extractall(path="/")
        print(">>> State bundle restored in seconds!")
    except Exception as e:
        print(f"Warning: Failed to extract state bundle: {{e}}")

# 3. Check for cached .deb packages
cached_debs = [f for f in os.listdir("/kaggle/working/cache/apt/archives") if f.endswith(".deb")]
if cached_debs:
    print(f">>> Installing {{len(cached_debs)}} cached .deb packages offline...")
    subprocess.run(["dpkg", "-i", "--skip-same-version"] + 
                   [os.path.join("/kaggle/working/cache/apt/archives", d) for d in cached_debs],
                   check=False)

# 4. Ensure essential tools and X11 forwarding libraries are present
print(">>> Verifying base packages (openssh-server, xauth, x11-apps, tmux, etc.)...")
subprocess.run(["apt-get", "update", "-qq"], check=False)
base_pkgs = [
    "openssh-server", "xauth", "x11-apps", "dbus-x11", "xvfb",
    "tmux", "htop", "rsync", "curl", "wget", "git", "net-tools",
    "vim", "nano", "jq", "ca-certificates"
]
subprocess.run(["apt-get", "install", "-y", "-qq", "--no-install-recommends"] + base_pkgs, check=True)

# 5. Create the fast 'server-save' command inside Kaggle
SAVE_SCRIPT = '''#!/usr/bin/env bash
set -e
echo ">>> Archiving Debian server state to /kaggle/working/debian_server_state.tar.gz..."
mkdir -p /kaggle/working/cache/apt/archives
tar -czf /kaggle/working/debian_server_state.tar.gz \\
    --exclude="/root/.cache" \\
    --exclude="/root/.local/share/Trash" \\
    -C / \\
    root/.bashrc \\
    root/.bash_history 2>/dev/null || true

# If root has local python packages or custom tools, include them
if [ -d "/root/.local" ]; then
    tar -rzf /kaggle/working/debian_server_state.tar.gz -C / root/.local 2>/dev/null || true
fi
if [ -d "/root/.config" ]; then
    tar -rzf /kaggle/working/debian_server_state.tar.gz -C / root/.config 2>/dev/null || true
fi
echo ">>> Saved! Bundle size: $(du -h /kaggle/working/debian_server_state.tar.gz | cut -f1)"
'''
with open("/usr/local/bin/server-save", "w") as f:
    f.write(SAVE_SCRIPT)
os.chmod("/usr/local/bin/server-save", 0o755)
print(">>> 'server-save' command installed in /usr/local/bin/server-save")
"""
        },

        # Cell 3: SSH Daemon & Web Terminal (ttyd) Setup
        {
            "cell_type": "code",
            "execution_count": None,
            "metadata": {},
            "outputs": [],
            "source": f"""# Cell 3: SSH Daemon & Web Terminal Setup
import os, subprocess, sys, urllib.request

AUTH_USER = "{auth_user}"
AUTH_PASS = "{auth_pass}"
PUB_KEY = "{pub_key}"

print(">>> Configuring OpenSSH server with X11 Forwarding...")
sshd_config = '''
Port 22
ListenAddress 0.0.0.0
PermitRootLogin yes
PasswordAuthentication yes
X11Forwarding yes
X11DisplayOffset 10
X11UseLocalhost no
PrintMotd yes
ClientAliveInterval 30
ClientAliveCountMax 10
AcceptEnv LANG LC_*
TCPKeepAlive yes
UseDNS no
Subsystem sftp internal-sftp
'''
with open("/etc/ssh/sshd_config", "w") as f:
    f.write(sshd_config.strip() + "\\n")

# Set root password
subprocess.run(f"echo 'root:{{AUTH_PASS}}' | chpasswd", shell=True, check=True)

# Add local SSH public key for instant key-based login
os.makedirs("/root/.ssh", exist_ok=True)
os.chmod("/root/.ssh", 0o700)
auth_keys_path = "/root/.ssh/authorized_keys"
if PUB_KEY:
    with open(auth_keys_path, "a") as f:
        f.write(PUB_KEY + "\\n")
    os.chmod(auth_keys_path, 0o600)
    print(">>> Injected local SSH public key into authorized_keys!")

# Generate host keys if missing and start SSH daemon
subprocess.run(["ssh-keygen", "-A"], check=False)
subprocess.run(["service", "ssh", "restart"], check=True)
print(">>> OpenSSH Daemon is running on port 22 with internal-sftp & X11 Forwarding enabled!")

# Install ttyd for Web Terminal
ttyd_path = "/kaggle/working/cache/bin/ttyd"
if not os.path.exists(ttyd_path):
    print(">>> Downloading ttyd binary (cached in persistent storage)...")
    url = "https://github.com/tsl0922/ttyd/releases/download/1.7.7/ttyd.x86_64"
    urllib.request.urlretrieve(url, ttyd_path)
    os.chmod(ttyd_path, 0o755)

# Symlink to /usr/local/bin
if not os.path.exists("/usr/local/bin/ttyd"):
    os.symlink(ttyd_path, "/usr/local/bin/ttyd")

# Start ttyd on port 7681 in background (-W for writable terminal)
# Gateway (server_gateway.py) already enforces HTTP Basic Auth at the perimeter.
subprocess.Popen([
    "/usr/local/bin/ttyd",
    "-W",
    "-p", "7681",
    "-b", "/terminal",
    "bash"
])
print(">>> ttyd Web Terminal running on 127.0.0.1:7681")

# Install and Launch Web VS Code (code-server) for 60fps zero-latency browser development
cs_deb = "/kaggle/working/cache/apt/archives/code-server_4.144.0_amd64.deb"
if not os.path.exists(cs_deb):
    print(">>> Downloading code-server package to persistent cache...")
    cs_url = "https://github.com/coder/code-server/releases/download/v4.144.0/code-server_4.144.0_amd64.deb"
    urllib.request.urlretrieve(cs_url, cs_deb)

if not shutil.which("code-server"):
    print(">>> Installing code-server from persistent cache...")
    subprocess.run(["dpkg", "-i", cs_deb], check=True)

subprocess.Popen([
    "code-server",
    "--bind-addr", "127.0.0.1:8085",
    "--auth", "none",
    "--disable-telemetry",
    "--disable-update-check",
    "/kaggle/working"
])
print(">>> Web VS Code (code-server) running on 127.0.0.1:8085")
"""
        },

        # Cell 4: Python Server Gateway & Cloudflare Tunnel
        {
            "cell_type": "code",
            "execution_count": None,
            "metadata": {},
            "outputs": [],
            "source": CELL4_SOURCE
        },

        # Cell 5: Keep-Alive Loop ("Kaggle Not Go Offline")
        {
            "cell_type": "code",
            "execution_count": None,
            "metadata": {},
            "outputs": [],
            "source": f"""# Cell 5: Heartbeat Watchdog & Keep-Alive Loop (Up to 12 Hours)
import time, os, subprocess, shutil

STOP_FLAG = "/kaggle/working/STOP_SERVER"
TOTAL_MINUTES = 715  # ~11 hours 55 minutes (just under 12-hour hard limit)

print(f">>> Keepalive watchdog running for ~{{TOTAL_MINUTES}} minutes...", flush=True)

for minute in range(TOTAL_MINUTES):
    for _ in range(6):  # Check every 10 seconds
        if os.path.exists(STOP_FLAG):
            print(">>> Shutdown flag detected (/kaggle/working/STOP_SERVER). Terminating gracefully...", flush=True)
            break
        time.sleep(10)

    if os.path.exists(STOP_FLAG):
        break

    # Touch heartbeat
    with open("/kaggle/working/HEARTBEAT", "w") as f:
        f.write(str(time.time()))

    # Print log message every 5 minutes to prevent Kaggle idle disconnect
    if minute % 5 == 0:
        st = shutil.disk_usage("/kaggle/working")
        print(f"[HEARTBEAT {{minute}}m] Server active | Free Disk: {{st.free / 1e9:.1f}} GB | Keepalive OK", flush=True)

# Final auto-save before exit
print(">>> Session ending. Auto-triggering server-save to preserve packages...")
subprocess.run(["/usr/local/bin/server-save"], check=False)
print(">>> Keepalive loop finished.", flush=True)
"""
        }
    ]

    notebook_content = {
        "cells": cells,
        "metadata": {
            "kernelspec": {
                "display_name": "Python 3",
                "language": "python",
                "name": "python3"
            },
            "language_info": {
                "name": "python",
                "version": "3.10"
            }
        },
        "nbformat": 4,
        "nbformat_minor": 5
    }

    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(notebook_content, f, indent=2)

    print(f"Generated {output_path} successfully ({len(cells)} cells).")


if __name__ == "__main__":
    out = os.path.join(ROOT, "notebook.ipynb")
    if len(sys.argv) > 1:
        out = sys.argv[1]
    generate_notebook(out)
